<?php
require 'includes/bootstrap.php'; require_admin(); require 'includes/layout.php';
require 'includes/home_content.php';
$resources = [
 'banners'=>['title'=>'Home slides','table'=>'banners','fields'=>['title','subtitle','link_url','sort_order'],'image'=>true],
 'offers'=>['title'=>'Home offers','table'=>'home_offers','fields'=>['title','subtitle','link_url','sort_order'],'image'=>true],
 'categories'=>['title'=>'Home categories','table'=>'categories','fields'=>['name_en','name_ar','icon','sort_order'],'image'=>false],
 'services'=>['title'=>'Travel services','table'=>'services','fields'=>['name_en','name_ar','short_description','price_from','sort_order'],'image'=>true],
 'destinations'=>['title'=>'Destinations & visas','table'=>'destinations','fields'=>['name_en','name_ar','country_code','sort_order'],'image'=>true],
 'hotels'=>['title'=>'Hotels','table'=>'hotels','fields'=>['name','city','country','star_rating','price_per_night','sort_order'],'image'=>true],
 'vehicles'=>['title'=>'Vehicles & drivers','table'=>'vehicles','fields'=>['name','vehicle_type','seats','price_per_day','driver_name','sort_order'],'image'=>true],
];
$type = $_GET['type'] ?? 'banners'; if (!isset($resources[$type])) redirect('content.php?type=banners'); $r=$resources[$type]; $table=$r['table'];
$isHomeContent=in_array($type,['banners','offers'],true);
if($type==='offers')db()->exec("CREATE TABLE IF NOT EXISTS home_offers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,subtitle VARCHAR(255),image_path VARCHAR(255),link_url VARCHAR(255),sort_order INT NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_home_offers_active_order(active,sort_order,id))");
if ($_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf(); $action=$_POST['action']??'save'; $id=(int)($_POST['id']??0); $wasEdit=$id>0;
 try {
  if(!in_array($action,['save','delete','toggle'],true))throw new RuntimeException('Invalid action.');
  if($action!=='save'&&$id<1)throw new RuntimeException('Item not found.');
  db()->beginTransaction();
  $existing=null;if($id){$lookup=db()->prepare("SELECT * FROM `$table` WHERE id=? FOR UPDATE");$lookup->execute([$id]);$existing=$lookup->fetch();if(!$existing)throw new RuntimeException('Item not found.');}
  if ($action==='delete') { $stmt=db()->prepare("DELETE FROM `$table` WHERE id=?"); $stmt->execute([$id]); if($isHomeContent){$entity=$type==='banners'?'banner':'home_offer';db()->prepare("INSERT INTO audit_log(admin_id,action,entity_type,entity_id,details_json) VALUES(?,?,?,?,?)")->execute([admin()['id'],$entity.'.deleted',$entity,(string)$id,'{}']);} flash('success','Item deleted.'); }
  elseif ($action==='toggle') { $stmt=db()->prepare("UPDATE `$table` SET active=1-active WHERE id=?"); $stmt->execute([$id]); if($isHomeContent){$entity=$type==='banners'?'banner':'home_offer';db()->prepare("INSERT INTO audit_log(admin_id,action,entity_type,entity_id,details_json) VALUES(?,?,?,?,?)")->execute([admin()['id'],$entity.'.visibility_changed',$entity,(string)$id,'{}']);} flash('success','Visibility updated.'); }
  else {
   $data=[]; foreach($r['fields'] as $f) $data[$f]=trim((string)($_POST[$f]??''));
   if($isHomeContent){if($data['link_url']!==''&&(!filter_var($data['link_url'],FILTER_VALIDATE_URL)||strtolower((string)parse_url($data['link_url'],PHP_URL_SCHEME))!=='https'))throw new RuntimeException('Use an HTTPS link or leave it empty.');if($data['title']==='')throw new RuntimeException($type==='banners'?'Slide title is required.':'Offer title is required.');$order=filter_var($data['sort_order'],FILTER_VALIDATE_INT);if($order===false||$order<0)throw new RuntimeException('Display order must be a non-negative integer.');$data['sort_order']=$order;}
   if ($r['image']) $data['image_path']=upload_image('image', $existing['image_path']??null);
   if($isHomeContent&&!public_asset_available($data['image_path']))throw new RuntimeException($type==='banners'?'A valid slide image is required. Upload a replacement for a missing file.':'A valid offer card image is required. Upload a replacement for a missing file.');
   $data['active']=isset($_POST['active'])?1:0;
   if ($id) { $set=implode(',',array_map(fn($k)=>"`$k`=?",array_keys($data))); $stmt=db()->prepare("UPDATE `$table` SET $set WHERE id=?"); $stmt->execute([...array_values($data),$id]); }
   else { $cols=implode(',',array_map(fn($k)=>"`$k`",array_keys($data))); $qs=implode(',',array_fill(0,count($data),'?')); $stmt=db()->prepare("INSERT INTO `$table` ($cols) VALUES ($qs)"); $stmt->execute(array_values($data)); }
   if($isHomeContent){if(!$id)$id=(int)db()->lastInsertId();$entity=$type==='banners'?'banner':'home_offer';db()->prepare("INSERT INTO audit_log(admin_id,action,entity_type,entity_id,details_json) VALUES(?,?,?,?,?)")->execute([admin()['id'],$entity.'.saved',$entity,(string)$id,json_encode(['sortOrder'=>(int)$data['sort_order'],'active'=>(bool)$data['active']])]);}flash('success',$wasEdit?'Item updated.':'Item created.');
  }
  db()->commit();
 } catch(Throwable $e){ if(db()->inTransaction())db()->rollBack();flash('error',$e instanceof PDOException?'Could not save this content. Please try again.':$e->getMessage()); }
 redirect('content.php?type='.$type);
}
$edit=null; if(isset($_GET['edit'])){$stmt=db()->prepare("SELECT * FROM `$table` WHERE id=?");$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch();}
$items=db()->query("SELECT * FROM `$table` ORDER BY sort_order ASC, id ASC")->fetchAll();
$labels=['title'=>'Title','subtitle'=>'Subtitle','link_url'=>'Optional tap link','sort_order'=>'Display order','name_en'=>'English name','name_ar'=>'Arabic name','icon'=>'Icon / emoji','short_description'=>'Short description','price_from'=>'Starting price','country_code'=>'Country code','name'=>'Name','city'=>'City','country'=>'Country','star_rating'=>'Star rating','price_per_night'=>'Price / night','vehicle_type'=>'Vehicle type','seats'=>'Seats','price_per_day'=>'Price / day','driver_name'=>'Driver name'];
page_header($r['title']); if($isHomeContent){home_content_navigation($type);?><section class="home-content-intro"><div><p class="eyebrow">PORTADA DE LA APP</p><h2><?=$type==='banners'?'Slides principales':'Ofertas destacadas'?></h2><p><?=$type==='banners'?'Gestiona las imágenes grandes que reciben a tus clientes.':'Publica las ofertas que aparecen debajo de los accesos a servicios.'?></p></div></section><?php } ?>
<div class="content-layout"><section class="panel"><div class="panel-head"><div><p class="eyebrow">APP CONTENT</p><h3><?= $edit?'Edit item':'Add new item' ?></h3></div><?php if($edit): ?><a href="content.php?type=<?=e($type)?>">Cancel</a><?php endif; ?></div><form method="post" enctype="multipart/form-data" class="editor-form" data-home-editor><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><input type="hidden" name="current_image" value="<?=e($edit['image_path']??'')?>"><?php foreach($r['fields'] as $f): ?><label><?=e($labels[$f]??ucfirst($f))?><?php if(in_array($f,['short_description','subtitle'],true)): ?><textarea name="<?=e($f)?>" rows="4"><?=e($edit[$f]??'')?></textarea><?php else: ?><input name="<?=e($f)?>" value="<?=e((string)($edit[$f]??($f==='sort_order'?0:'')))?>" <?= str_contains($f,'price')||in_array($f,['sort_order','seats','star_rating'])?'type="number" step="0.01"':'' ?>></label><?php endif; ?><?php endforeach; ?><?php if($r['image']): ?><label><?=$type==='banners'?'Slide image':($type==='offers'?'Offer card image':'Cover image')?><input type="file" name="image" accept="image/jpeg,image/png,image/webp" data-home-image></label><?php endif; ?><label class="check"><input type="checkbox" name="active" <?=($edit['active']??1)?'checked':''?>> Visible in mobile app</label><button class="btn primary wide"><?= $edit?'Save changes':'Create item' ?> →</button></form></section>
<section class="panel list-panel"><div class="panel-head"><div><p class="eyebrow">PUBLISHED CONTENT</p><h3><?=count($items)?> items</h3></div></div><div class="cards-list"><?php foreach($items as $item): ?><?php $assetOk=!$r['image']||public_asset_available($item['image_path']??null);$assetUrl=$assetOk&&$r['image']?public_content_media_url($type,(int)$item['id'],$item['image_path']):'assets/placeholder.svg';?><article class="content-card"><?php if($r['image']): ?><div class="thumb" style="background-image:url('<?=e($assetUrl)?>')"></div><?php else: ?><div class="thumb icon-thumb"><?=e($item['icon']??'◇')?></div><?php endif; ?><div class="card-info"><strong><?=e($item['title']??$item['name_en']??$item['name']??'Untitled')?></strong><small><?=e($item['subtitle']??$item['name_ar']??$item['city']??$item['vehicle_type']??'')?><?php if($isHomeContent):?> · Order <?=(int)$item['sort_order']?><?php endif;?></small><span class="visibility <?= !$assetOk?'off':($item['active']?'on':'off') ?>"><?=!$assetOk?'Missing image — edit and re-upload':($item['active']?'Visible':'Hidden')?></span></div><div class="card-actions"><a href="?type=<?=e($type)?>&edit=<?=(int)$item['id']?>">Edit</a><form method="post"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button name="action" value="toggle">Toggle</button><button class="danger" name="action" value="delete" data-confirm="Delete this item permanently?">Delete</button></form></div></article><?php endforeach; ?><?php if(!$items): ?><div class="empty-state">No content yet. Add the first item using the form.</div><?php endif; ?></div></section></div>
<?php page_footer();
